INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_MILLIONS', 'MATH.G6.NUMBER.WHOLE_NUMBERS', 'mathematics', 6, 'Place value of digits up to millions', ARRAY['MATH.G6.NUMBER.WHOLE_NUMBERS.a']::text[], 'Given a whole number up to 9,999,999, the child names the place of any digit (ones to millions), including digits beside zeros, and says which digit is in a named place. Numbers in real settings such as a county population or a school budget.', '["name the place of a digit","which digit is in the given place","read a place value chart","missing digit from clues"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_MILLIONS', 'MATH.G6.NUMBER.WHOLE_NUMBERS', 'mathematics', 6, 'Total value of digits up to millions', ARRAY['MATH.G6.NUMBER.WHOLE_NUMBERS.a']::text[], 'Given a whole number up to 9,999,999 the child gives the total value of a chosen digit (digit times its place) and writes the number in expanded form. The child does not confuse the total value of a digit with its place value.', '["total value of an underlined digit","expanded form","difference between two digits of the same value","build a number from total values"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SYMBOLS_MILLIONS', 'MATH.G6.NUMBER.WHOLE_NUMBERS', 'mathematics', 6, 'Write numbers up to millions in symbols', ARRAY['MATH.G6.NUMBER.WHOLE_NUMBERS.b']::text[], 'Given a number said or described in parts (for example 3 million, 45 thousand and 7) the child writes it in symbols with every place filled, using zero as a place holder. Numbers up to 9,999,999.', '["write from parts","choose the number in symbols","spot the missing zero","read a number aloud and write it"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.READ_WRITE_WORDS_100K', 'MATH.G6.NUMBER.WHOLE_NUMBERS', 'mathematics', 6, 'Read and write numbers up to 100,000 in words', ARRAY['MATH.G6.NUMBER.WHOLE_NUMBERS.c']::text[], 'The child writes a number up to 100,000 in words (British spelling, hyphen in twenty-one to ninety-nine) and writes a number given in words in figures. Limit as the design sets it: 100,000.', '["figures to words","words to figures","which word form matches","spot the spelling or place mistake"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K', 'MATH.G6.NUMBER.WHOLE_NUMBERS', 'mathematics', 6, 'Order numbers up to 100,000', ARRAY['MATH.G6.NUMBER.WHOLE_NUMBERS.d']::text[], 'The child orders a list of four to five numbers up to 100,000 from smallest to largest and largest to smallest, comparing digit counts first and then place by place from the left. Uses < and > correctly.', '["order a list","which is largest or smallest","insert < or >","order real quantities such as crowds or prices"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND', 'MATH.G6.NUMBER.WHOLE_NUMBERS', 'mathematics', 6, 'Round numbers up to 100,000 to the nearest thousand', ARRAY['MATH.G6.NUMBER.WHOLE_NUMBERS.e']::text[], 'The child rounds any whole number up to 100,000 to the nearest 1,000: looks at the hundreds digit, rounds 500 up, and keeps the answer in thousands (for example 49,500 rounds to 50,000).', '["round a number","round in a real situation","which number rounds to","spot the rounding mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARES_TO_100', 'MATH.G6.NUMBER.WHOLE_NUMBERS', 'mathematics', 6, 'Squares of whole numbers up to 100', ARRAY['MATH.G6.NUMBER.WHOLE_NUMBERS.f']::text[], 'The child works out the square of a whole number up to 100 as the number times itself (for example 40 squared is 1,600) and recalls the squares of 1 to 12 from memory. Squares of 13 to 100 are worked out, not recalled.', '["square of a number","area of a square plot","which is a square number","spot: doubled instead of squared"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_SQUARES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARE_ROOTS_10000', 'MATH.G6.NUMBER.WHOLE_NUMBERS', 'mathematics', 6, 'Square roots of perfect squares up to 10,000', ARRAY['MATH.G6.NUMBER.WHOLE_NUMBERS.g']::text[], 'Given a perfect square up to 10,000 the child finds its square root and checks it by squaring. The child can say that a number such as 50 is not a perfect square because no whole number multiplied by itself gives 50.', '["find the square root","side of a square from its area","is it a perfect square, and why","check a root by squaring"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_SQUARES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D', 'MATH.G6.NUMBER.MULTIPLICATION', 'mathematics', 6, 'Multiply a 4-digit number by a 2-digit number', ARRAY['MATH.G6.NUMBER.MULTIPLICATION.a']::text[], 'The child multiplies a number up to 4 digits by a 2-digit number by the standard written method (two partial products, with zero placed in the ones of the tens row) or by partitioning, and solves a story that needs it. Products below 1,000,000.', '["calculate the product","story problem","find the missing digit","spot the mistake in a partial product"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_MULTIPLICATION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10', 'MATH.G6.NUMBER.MULTIPLICATION', 'mathematics', 6, 'Estimate products by rounding to the nearest ten', ARRAY['MATH.G6.NUMBER.MULTIPLICATION.b']::text[], 'The child rounds both numbers to the nearest ten, multiplies the rounded numbers, and says whether an exact answer is sensible. Rounding to the nearest ten for both factors, as outcome b says.', '["estimate a cost","choose the best estimate","spot the rounding mistake","is this answer sensible?"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_MULTIPLICATION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_PATTERNS', 'MATH.G6.NUMBER.MULTIPLICATION', 'mathematics', 6, 'Make and continue multiplication patterns (numbers up to 1,000)', ARRAY['MATH.G6.NUMBER.MULTIPLICATION.c']::text[], 'The child finds the rule of a pattern made by multiplying (for example times 2 or times 3), continues it, and finds a missing term. Terms do not exceed 1,000.', '["continue the pattern","find the rule from a table","missing term","choose the rule"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_PATTERNS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D', 'MATH.G6.NUMBER.DIVISION', 'mathematics', 6, 'Divide up to a 4-digit number by up to a 3-digit number', ARRAY['MATH.G6.NUMBER.DIVISION.a']::text[], 'The child divides a 4-digit number by a 1-, 2- or 3-digit number by long division, with the dividend greater than the divisor, gives any remainder as a whole number, and checks by multiplying back and adding the remainder.', '["calculate the quotient","story problem with a remainder","check by multiplying","spot the mistake in the working"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_DIVISION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DIVISION.ESTIMATE_QUOTIENT', 'MATH.G6.NUMBER.DIVISION', 'mathematics', 6, 'Estimate quotients by rounding to the nearest ten', ARRAY['MATH.G6.NUMBER.DIVISION.b']::text[], 'The child rounds the dividend and divisor to the nearest ten, divides the rounded numbers, and uses the estimate to check that an exact answer is sensible.', '["estimate how many trips","choose the best estimate","is the answer sensible?"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_DIVISION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DIVISION.COMBINED_OPERATIONS', 'MATH.G6.NUMBER.DIVISION', 'mathematics', 6, 'Combined operations with the four operations (up to 3-digit numbers)', ARRAY['MATH.G6.NUMBER.DIVISION.c']::text[], 'The child works out an expression with two or three of the four operations, doing multiplication and division before addition and subtraction and working left to right within each level, with numbers up to 3 digits. Brackets are taken first where they appear.', '["calculate the expression","choose the correct value","story needing two operations","spot the step done in the wrong order"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_DIVISION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_FRACTIONS_LCM', 'MATH.G6.NUMBER.FRACTIONS', 'mathematics', 6, 'Add fractions with unlike denominators using the LCM', ARRAY['MATH.G6.NUMBER.FRACTIONS.a']::text[], 'The child finds the LCM of two denominators (each up to 12), renames both fractions with it, adds the numerators, keeps the denominator, and simplifies. Sums that exceed 1 are written as a mixed number.', '["add two fractions in a story","complete the steps","why we need a common denominator","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_FRACTIONS_LCM', 'MATH.G6.NUMBER.FRACTIONS', 'mathematics', 6, 'Subtract fractions with unlike denominators using the LCM', ARRAY['MATH.G6.NUMBER.FRACTIONS.b']::text[], 'The child renames two unlike fractions with the LCM of their denominators (each up to 12), subtracts the numerators, keeps the denominator, and simplifies. The first fraction is larger.', '["subtract in a story","complete the steps","spot the mistake","what is left"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_MIXED_NUMBERS', 'MATH.G6.NUMBER.FRACTIONS', 'mathematics', 6, 'Add mixed numbers', ARRAY['MATH.G6.NUMBER.FRACTIONS.c']::text[], 'The child adds two mixed numbers by adding the wholes and the fractions separately (using the LCM when the denominators differ) or by changing to improper fractions, and writes the answer in simplest form, renaming when the fractions total more than 1.', '["add two mixed numbers","change a mixed number to an improper fraction","spot the mistake in the conversion","story with lengths or masses"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_MIXED_NUMBERS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_MIXED_NUMBERS', 'MATH.G6.NUMBER.FRACTIONS', 'mathematics', 6, 'Subtract mixed numbers', ARRAY['MATH.G6.NUMBER.FRACTIONS.d']::text[], 'The child subtracts one mixed number from a larger one, including the case where the fraction part is too small and one whole must be renamed, and gives the answer in simplest form.', '["subtract in a story","complete the steps","spot the mistake when the fraction is too small","choose the answer"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_MIXED_NUMBERS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.RECIPROCAL', 'MATH.G6.NUMBER.FRACTIONS', 'mathematics', 6, 'Reciprocal of a proper fraction', ARRAY['MATH.G6.NUMBER.FRACTIONS.e']::text[], 'The child writes the reciprocal of a proper fraction whose numerator and denominator are up to 2 digits by turning it upside down, and knows that a number times its reciprocal is 1.', '["write the reciprocal","check that the product is 1","which pair are reciprocals","why has a whole number no reciprocal fraction written 0"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_MIXED_NUMBERS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SQUARE_OF_FRACTION', 'MATH.G6.NUMBER.FRACTIONS', 'mathematics', 6, 'Square of a fraction', ARRAY['MATH.G6.NUMBER.FRACTIONS.f']::text[], 'The child squares a fraction with a one-digit numerator and a denominator of up to 2 digits by squaring the numerator and the denominator, and writes the answer in simplest form.', '["square the fraction","story about area of a square cloth","spot: squared only the top","choose the correct square"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_SQUARES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.FRACTION_TO_PERCENT', 'MATH.G6.NUMBER.FRACTIONS', 'mathematics', 6, 'Express a fraction as a percentage', ARRAY['MATH.G6.NUMBER.FRACTIONS.g']::text[], 'The child writes a fraction as a percentage by making the denominator 100 or by dividing and multiplying by 100, including fractions with denominators that are factors of 100 and a mark out of a total.', '["write a score as a percentage","which fraction is the larger percentage","percentage from a table","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_PERCENTAGES_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.PERCENT_TO_FRACTION', 'MATH.G6.NUMBER.FRACTIONS', 'mathematics', 6, 'Convert a percentage to a fraction', ARRAY['MATH.G6.NUMBER.FRACTIONS.h']::text[], 'The child writes a percentage as a fraction out of 100 and simplifies it to simplest form.', '["write as a fraction","simplest form","choose the equivalent fraction","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_PERCENTAGES_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_PLACES_TEN_THOUSANDTHS', 'MATH.G6.NUMBER.DECIMALS', 'mathematics', 6, 'Identify decimals up to ten-thousandths', ARRAY['MATH.G6.NUMBER.DECIMALS.a']::text[], 'The child names the place of a digit after the decimal point up to ten-thousandths, gives its value as a fraction, and writes a decimal from a place description (for example 7 ten-thousandths as 0.0007).', '["name the place","write the decimal from its words","value of a digit","compare two decimals by place"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ROUND_DECIMALS_3DP', 'MATH.G6.NUMBER.DECIMALS', 'mathematics', 6, 'Round decimals to up to 3 decimal places', ARRAY['MATH.G6.NUMBER.DECIMALS.b']::text[], 'The child rounds a decimal to 1, 2 or 3 decimal places by looking at the next digit, including when the rounding carries across a 9 (for example 4.9996 to 3 places is 5.000).', '["round to a stated place","round a measurement","spot the rounding mistake","which number rounds to"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_FRACTION', 'MATH.G6.NUMBER.DECIMALS', 'mathematics', 6, 'Convert decimals to fractions', ARRAY['MATH.G6.NUMBER.DECIMALS.c']::text[], 'The child writes a decimal with up to 3 places as a fraction with denominator 10, 100 or 1,000 and simplifies it.', '["write as a simplest fraction","table of fraction, decimal, percentage","which fraction equals the decimal","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DECIMALS.FRACTION_TO_DECIMAL', 'MATH.G6.NUMBER.DECIMALS', 'mathematics', 6, 'Convert fractions to decimals', ARRAY['MATH.G6.NUMBER.DECIMALS.c']::text[], 'The child writes a fraction as a decimal by dividing the numerator by the denominator or by renaming it with denominator 10, 100 or 1,000 (denominators such as 2, 4, 5, 8, 10, 20, 25, 50).', '["write as a decimal","choose the decimal","complete a conversion table","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_PERCENT', 'MATH.G6.NUMBER.DECIMALS', 'mathematics', 6, 'Convert decimals to percentages', ARRAY['MATH.G6.NUMBER.DECIMALS.d']::text[], 'The child writes a decimal as a percentage by multiplying by 100 (moving the point two places), including decimals less than 0.1 and more than 1.', '["write as a percentage","story about a tank or a score","table of equivalent forms","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DECIMALS.PERCENT_TO_DECIMAL', 'MATH.G6.NUMBER.DECIMALS', 'mathematics', 6, 'Convert percentages to decimals', ARRAY['MATH.G6.NUMBER.DECIMALS.d']::text[], 'The child writes a percentage as a decimal by dividing by 100 (moving the point two places left), including 5%, 0.5% and 120%.', '["write as a decimal","discount story","table of equivalent forms","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ADD_DECIMALS_4DP', 'MATH.G6.NUMBER.DECIMALS', 'mathematics', 6, 'Add decimals up to 4 decimal places', ARRAY['MATH.G6.NUMBER.DECIMALS.e']::text[], 'The child adds two or three decimals with up to 4 decimal places in columns with the points in line, filling empty places with zeros.', '["add two decimals","add several amounts in a story","spot the misaligned point","choose the total"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.DECIMALS.SUBTRACT_DECIMALS_4DP', 'MATH.G6.NUMBER.DECIMALS', 'mathematics', 6, 'Subtract decimals up to 4 decimal places', ARRAY['MATH.G6.NUMBER.DECIMALS.f']::text[], 'The child subtracts one decimal from another with up to 4 decimal places in columns with the points in line, renaming across zeros and filling empty places with zeros.', '["subtract in a story","subtract from a whole number","spot the mistake","check by adding"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.FORM_INEQUALITY', 'MATH.G6.NUMBER.INEQUALITIES', 'mathematics', 6, 'Form a simple inequality in one unknown from a situation', ARRAY['MATH.G6.NUMBER.INEQUALITIES.a']::text[], 'The child writes an inequality using <, >, at least, at most, from a short story (for example "at least 30 learners" as x >= 30 or "fewer than 12" as x < 12) and chooses the right symbol.', '["write the inequality","choose the symbol","which story matches","list numbers that fit"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_INEQUALITIES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SIMPLIFY_INEQUALITY', 'MATH.G6.NUMBER.INEQUALITIES', 'mathematics', 6, 'Simplify an inequality in one unknown', ARRAY['MATH.G6.NUMBER.INEQUALITIES.b']::text[], 'The child simplifies an inequality such as x + 5 < 12 or 3x > 18 in one step to x < 7 or x > 6 by doing the same operation to both sides, and keeps the symbol pointing the same way.', '["simplify one step","story that gives an inequality","spot the mistake","choose the simplified form"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_INEQUALITIES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY', 'MATH.G6.NUMBER.INEQUALITIES', 'mathematics', 6, 'Solve a simple inequality in one unknown', ARRAY['MATH.G6.NUMBER.INEQUALITIES.c']::text[], 'The child solves a one-step or two-step inequality, lists the whole-number solutions or the largest or smallest one, and checks a value by substituting. No negative multipliers or divisors.', '["solve","largest whole number that fits","count the solutions","spot the mistake","check a value"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_INEQUALITIES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_AS_UNIT', 'MATH.G6.MEASUR.LENGTH', 'mathematics', 6, 'Use the millimetre as a unit of length', ARRAY['MATH.G6.MEASUR.LENGTH.a']::text[], 'The child chooses the sensible unit (mm, cm, m or km) for a small length such as a coin, a pencil lead or a wire thickness, and reads a length to the nearest millimetre on a ruler.', '["choose the best unit","read a ruler to the nearest mm","which object is measured in mm","estimate a small length in mm"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_UNIT_CONVERSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_CM_RELATIONSHIP', 'MATH.G6.MEASUR.LENGTH', 'mathematics', 6, 'The relationship between the millimetre and the centimetre', ARRAY['MATH.G6.MEASUR.LENGTH.b']::text[], 'The child knows that 1 cm is 10 mm and uses it to say how many mm are in a number of cm and how many cm in a number of mm (whole and half centimetres), for example 25 mm is 2 cm and 5 mm.', '["how many mm in a cm","marks on a ruler","cm and mm as a mixed length","which is longer"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_UNIT_CONVERSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.LENGTH.CONVERT_TO_MM', 'MATH.G6.MEASUR.LENGTH', 'mathematics', 6, 'Convert centimetres and millimetres to millimetres', ARRAY['MATH.G6.MEASUR.LENGTH.c']::text[], 'The child changes a length given in cm, or in cm and mm, to mm (multiply the cm by 10 and add the mm), for lengths up to 1,000 mm.', '["convert to mm","mixed length to mm","compare two lengths","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_UNIT_CONVERSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.LENGTH.ADD_CM_MM', 'MATH.G6.MEASUR.LENGTH', 'mathematics', 6, 'Add centimetres and millimetres', ARRAY['MATH.G6.MEASUR.LENGTH.d']::text[], 'The child adds two lengths in cm and mm, adds mm to mm and cm to cm, and renames 10 mm or more as cm, giving the answer as cm and mm.', '["add two lengths","total of several pieces","spot the missing rename","story about a fence or ribbon"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_UNIT_CONVERSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.LENGTH.SUBTRACT_CM_MM', 'MATH.G6.MEASUR.LENGTH', 'mathematics', 6, 'Subtract centimetres and millimetres', ARRAY['MATH.G6.MEASUR.LENGTH.e']::text[], 'The child subtracts one length in cm and mm from a longer one, renaming 1 cm as 10 mm when the mm are too few.', '["subtract two lengths","what is left of a ribbon","spot the mistake when mm are too few","check by adding"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_UNIT_CONVERSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.LENGTH.MULTIPLY_CM_MM', 'MATH.G6.MEASUR.LENGTH', 'mathematics', 6, 'Multiply centimetres and millimetres by a whole number', ARRAY['MATH.G6.MEASUR.LENGTH.f']::text[], 'The child multiplies a length in cm and mm by a whole number (up to 12), multiplies each part and renames mm of 10 or more as cm.', '["multiply a length","equal pieces laid end to end","spot the missing rename","total of several equal lengths"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_UNIT_CONVERSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.LENGTH.DIVIDE_CM_MM', 'MATH.G6.MEASUR.LENGTH', 'mathematics', 6, 'Divide centimetres and millimetres by a whole number', ARRAY['MATH.G6.MEASUR.LENGTH.g']::text[], 'The child divides a length in cm and mm into a whole number of equal parts (up to 12), changing to mm when the cm do not divide exactly, and gives the answer in cm and mm.', '["share a length equally","how long is each piece","spot the leftover cm not renamed","check by multiplying"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_UNIT_CONVERSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_PRACTICAL', 'MATH.G6.MEASUR.LENGTH', 'mathematics', 6, 'Determine the circumference of a circle practically', ARRAY['MATH.G6.MEASUR.LENGTH.h']::text[], 'The child reads a circumference measured with string or a tape (the length round the edge) and uses a measured table of circumference and diameter to work out a missing one, and the distance a wheel rolls in turns. The measuring itself is a hands-on task and stays with a practical.', '["read measured values from a table","use the pattern to find a missing value","distance rolled by a wheel","which tool measures round the edge"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_UNIT_CONVERSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_DIAMETER_RELATION', 'MATH.G6.MEASUR.LENGTH', 'mathematics', 6, 'The relationship between circumference and diameter', ARRAY['MATH.G6.MEASUR.LENGTH.i']::text[], 'The child knows that the circumference of a circle is about 3 times its diameter (pi, with 22/7 or 3.14 given in the question), finds the circumference from the diameter and the diameter from the circumference, and knows that the diameter is twice the radius.', '["circumference from diameter","diameter from circumference","is the answer sensible (about 3 times)","radius, diameter and distance round"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_UNIT_CONVERSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_TRIANGLE', 'MATH.G6.MEASUR.AREA', 'mathematics', 6, 'Area of triangles in square centimetres', ARRAY['MATH.G6.MEASUR.AREA.a']::text[], 'The child works out the area of a triangle as half of base times height in cm2, with the height at right angles to the base, and finds a missing base or height from the area.', '["area from base and height","find the missing height","story about a flower bed or a sail","spot: forgot to halve"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_AREA_TRIANGLE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_COMBINED', 'MATH.G6.MEASUR.AREA', 'mathematics', 6, 'Area of combined shapes of squares, rectangles and triangles', ARRAY['MATH.G6.MEASUR.AREA.b']::text[], 'The child splits a shape made of squares, rectangles and triangles into parts, finds each part''s area in cm2 and adds (or subtracts a cut-out), giving the area in cm2.', '["area of an L-shape","area of a shape with a triangle on top","subtract the cut-out","spot the missing part"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_AREA_RECT']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_CIRCLE_BY_COUNTING', 'MATH.G6.MEASUR.AREA', 'mathematics', 6, 'Estimate the area of a circle by counting squares', ARRAY['MATH.G6.MEASUR.AREA.c']::text[], 'The child estimates the area of a circle drawn on squared paper by counting whole squares and adding half for the part-squares, and says the answer is an estimate.', '["estimate by counting","half the part-squares","why the answer is only an estimate","which estimate is sensible"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_AREA_RECT']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.CAPACITY.CM3_ML_LITRE_RELATION', 'MATH.G6.MEASUR.CAPACITY', 'mathematics', 6, 'The relationship among cm3, millilitres and litres', ARRAY['MATH.G6.MEASUR.CAPACITY.a']::text[], 'The child knows that 1 cm3 holds 1 ml and that 1,000 cm3 (1,000 ml) is 1 litre, and uses this to say the capacity of a small cube or a box in ml or litres.', '["capacity of a cube of side 1 cm","litres to cm3","a box of 1,000 cm3 holds how many litres","match equal amounts"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_CAPACITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.CAPACITY.LITRES_TO_ML', 'MATH.G6.MEASUR.CAPACITY', 'mathematics', 6, 'Convert litres to millilitres', ARRAY['MATH.G6.MEASUR.CAPACITY.b']::text[], 'The child changes litres, or litres and millilitres, to millilitres (multiply the litres by 1,000, add the ml), including decimals of a litre such as 2.5 l.', '["convert to ml","story about bottles or a jug","compare two amounts","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_CAPACITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.CAPACITY.ML_TO_LITRES', 'MATH.G6.MEASUR.CAPACITY', 'mathematics', 6, 'Convert millilitres to litres', ARRAY['MATH.G6.MEASUR.CAPACITY.c']::text[], 'The child changes millilitres to litres (divide by 1,000) and gives litres and millilitres, or a decimal of a litre, for amounts up to 10,000 ml.', '["convert to litres","how many full bottles","litres and ml","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_CAPACITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MASS.TONNE_AS_UNIT', 'MATH.G6.MEASUR.MASS', 'mathematics', 6, 'Identify the tonne as a unit of mass', ARRAY['MATH.G6.MEASUR.MASS.a']::text[], 'The child knows the tonne (t) as a unit for very heavy masses and that it is bigger than the kilogramme, and chooses g, kg or t for a stated object.', '["choose the unit","which is heavier","what does t stand for"]'::jsonb, '["recall"]'::jsonb, ARRAY['G6_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MASS.ITEMS_IN_TONNES', 'MATH.G6.MEASUR.MASS', 'mathematics', 6, 'Identify items measured in tonnes', ARRAY['MATH.G6.MEASUR.MASS.b']::text[], 'The child picks from a list the items whose mass is given in tonnes (a lorry, a heap of sand, a harvest of maize) and not those given in kg or g.', '["which is measured in tonnes","choose the sensible mass for a lorry or an elephant","sort items into g, kg and t"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MASS.KG_TONNE_RELATIONSHIP', 'MATH.G6.MEASUR.MASS', 'mathematics', 6, 'The relationship between the kilogramme and the tonne', ARRAY['MATH.G6.MEASUR.MASS.c']::text[], 'The child knows that 1 tonne is 1,000 kg and uses it to say how many equal sacks make a tonne, for example how many 50 kg sacks.', '["how many kg in a tonne","sacks in a tonne","which is greater: kg or t","match equal masses"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MASS.ESTIMATE_TONNES', 'MATH.G6.MEASUR.MASS', 'mathematics', 6, 'Estimate mass in tonnes', ARRAY['MATH.G6.MEASUR.MASS.d']::text[], 'The child estimates the mass of a large load in tonnes from a familiar comparison (a bag of maize 90 kg, a lorry load of sacks) and chooses a sensible estimate.', '["choose the sensible estimate","estimate the load of a lorry","estimate from the number of sacks"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G6_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MASS.CONVERT_KG_TONNES', 'MATH.G6.MEASUR.MASS', 'mathematics', 6, 'Convert kilogrammes to tonnes and tonnes to kilogrammes', ARRAY['MATH.G6.MEASUR.MASS.e']::text[], 'The child changes tonnes, or tonnes and kilogrammes, to kilogrammes (multiply by 1,000, add the kg) and kilogrammes to tonnes (divide by 1,000, giving t and kg or a decimal).', '["tonnes to kg","kg to tonnes","total of bags in tonnes","spot the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MASS.ADD_TONNES_KG', 'MATH.G6.MEASUR.MASS', 'mathematics', 6, 'Add tonnes and kilogrammes', ARRAY['MATH.G6.MEASUR.MASS.f']::text[], 'The child adds two masses in tonnes and kilogrammes, adds kg to kg and t to t, and renames 1,000 kg or more as tonnes.', '["add two loads","total of several deliveries","spot the missing rename"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MASS.SUBTRACT_TONNES_KG', 'MATH.G6.MEASUR.MASS', 'mathematics', 6, 'Subtract tonnes and kilogrammes', ARRAY['MATH.G6.MEASUR.MASS.g']::text[], 'The child subtracts one mass in tonnes and kilogrammes from a larger one, renaming 1 tonne as 1,000 kg when the kg are too few.', '["what is left of a load","spot the mistake when kg are too few","check by adding"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MASS.MULTIPLY_TONNES_KG', 'MATH.G6.MEASUR.MASS', 'mathematics', 6, 'Multiply tonnes and kilogrammes by a whole number', ARRAY['MATH.G6.MEASUR.MASS.h']::text[], 'The child multiplies a mass in tonnes and kilogrammes by a whole number (up to 12) and renames kg of 1,000 or more as tonnes.', '["total of equal loads","trips of a lorry","spot the missing rename"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MASS.DIVIDE_TONNES_KG', 'MATH.G6.MEASUR.MASS', 'mathematics', 6, 'Divide tonnes and kilogrammes by a whole number', ARRAY['MATH.G6.MEASUR.MASS.i']::text[], 'The child divides a mass in tonnes and kilogrammes into equal parts (up to 12), changing to kg when the tonnes do not divide exactly.', '["share a load equally","mass of each part","spot the mistake","check by multiplying"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_IDENTIFY', 'MATH.G6.MEASUR.TIME', 'mathematics', 6, 'Identify time in a.m. and p.m.', ARRAY['MATH.G6.MEASUR.TIME.a']::text[], 'The child says whether an everyday event (breakfast, assembly, evening news) happens in the a.m. or the p.m. and knows that a.m. is from midnight to noon and p.m. from noon to midnight.', '["a.m. or p.m. for an event","which time is after noon","put events in order","noon and midnight"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.TIME.WRITE_AM_PM', 'MATH.G6.MEASUR.TIME', 'mathematics', 6, 'Write time in a.m. and p.m.', ARRAY['MATH.G6.MEASUR.TIME.b']::text[], 'The child writes a time shown on a clock or described in words with a.m. or p.m. (for example 7:30 p.m.), including 12 noon and 12 midnight.', '["write the time with a.m. or p.m.","read a clock and write the time","which is correct","spot the mistake at 12"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_TO_24H_RELATE', 'MATH.G6.MEASUR.TIME', 'mathematics', 6, 'Relate a.m. and p.m. time to the 24-hour clock', ARRAY['MATH.G6.MEASUR.TIME.c']::text[], 'The child matches times in a.m. and p.m. to the 24-hour clock (for example 3 p.m. and 15:00) and sees that the hours after noon are 12 more than on the 12-hour clock.', '["which 24-hour time matches","which 12-hour time matches","on the same clock face","timetable in both systems"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.TIME.CONVERT_12_24', 'MATH.G6.MEASUR.TIME', 'mathematics', 6, 'Convert time from the 12-hour to the 24-hour system and back', ARRAY['MATH.G6.MEASUR.TIME.d']::text[], 'The child writes a 12-hour time in 24-hour form (add 12 hours to p.m. times other than 12 noon, 12 a.m. is 00:00) and a 24-hour time in 12-hour form with a.m. or p.m.', '["to the 24-hour clock","to the 12-hour clock","spot the mistake at noon or midnight","choose the matching time"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.TIME.TRAVEL_TIMETABLE', 'MATH.G6.MEASUR.TIME', 'mathematics', 6, 'Interpret a travel timetable', ARRAY['MATH.G6.MEASUR.TIME.e']::text[], 'The child reads a table of departure and arrival times, in the 12-hour or 24-hour system, and works out the length of a journey, the waiting time and the shortest or earliest trip.', '["journey time","waiting time between buses","earliest bus","which trip is shortest"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MONEY.PREPARE_BUDGET', 'MATH.G6.MEASUR.MONEY', 'mathematics', 6, 'Prepare a simple budget', ARRAY['MATH.G6.MEASUR.MONEY.a']::text[], 'The child lists income and planned spending in a table, totals each, and finds the balance (income less spending) and whether the budget is over or under.', '["balance of a budget","is the budget over?","complete the budget table","which item to reduce"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE', 'MATH.G6.MEASUR.MONEY', 'mathematics', 6, 'Determine buying and selling prices', ARRAY['MATH.G6.MEASUR.MONEY.b']::text[], 'The child tells the buying price (cost) from the selling price, works out the selling price from the buying price and the profit or loss, and the buying price from the selling price and profit or loss.', '["selling price from cost and profit","buying price from selling price and profit","which is the buying price","selling price after a loss"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES', 'MATH.G6.MEASUR.MONEY', 'mathematics', 6, 'Work out profit from sales', ARRAY['MATH.G6.MEASUR.MONEY.c']::text[], 'The child works out profit as selling price less buying price when the selling price is greater, for a single item or for a number of items bought and sold together.', '["profit on one item","profit on several items","total cost then profit","story with spoilt goods"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES', 'MATH.G6.MEASUR.MONEY', 'mathematics', 6, 'Calculate loss from sales', ARRAY['MATH.G6.MEASUR.MONEY.d']::text[], 'The child works out the loss as buying price less selling price when the selling price is less, and decides from the two prices whether the sale made a profit or a loss.', '["loss on one item","profit or loss?","loss on several items","selling price after a loss"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.MEASUR.MONEY.TYPES_OF_TAXES', 'MATH.G6.MEASUR.MONEY', 'mathematics', 6, 'Identify types of taxes', ARRAY['MATH.G6.MEASUR.MONEY.e']::text[], 'The child names common taxes in Kenya (VAT on goods, PAYE on pay, import duty, land rates) and says what each is charged on, and works out an amount of tax or a total when a rate is stated in the question.', '["which tax is on goods","which tax is taken from pay","price plus VAT","take-home pay on a pay slip"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.LINES.PARALLEL_LINES', 'MATH.G6.GEOMET.LINES', 'mathematics', 6, 'Draw parallel lines: what makes lines parallel', ARRAY['MATH.G6.GEOMET.LINES.a']::text[], 'The child knows that parallel lines are always the same distance apart and never meet, picks them out from a set of lines in the environment (rails, ruled lines, a window frame), and says that a set square slid along a ruler draws them.', '["which pair is parallel","parallel lines in the environment","how to draw parallel lines","spot the pair that will meet"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_LINES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.LINES.BISECT_LINES', 'MATH.G6.GEOMET.LINES', 'mathematics', 6, 'Bisect a line: the idea of the midpoint', ARRAY['MATH.G6.GEOMET.LINES.b']::text[], 'The child knows that to bisect is to cut into two equal parts, that the bisector of a line meets it at its midpoint at a right angle, works out each half of a line of given length, and knows the compass arcs have the same radius on both ends.', '["length of each half","what does bisect mean","which step of the construction is wrong","midpoint of a line"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_LINES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.LINES.PERPENDICULAR_LINES', 'MATH.G6.GEOMET.LINES', 'mathematics', 6, 'Construct perpendicular lines: right angles', ARRAY['MATH.G6.GEOMET.LINES.c']::text[], 'The child knows that perpendicular lines meet at a right angle (90 degrees), picks out perpendicular lines in the environment (wall and floor, a window corner), and says that a set square or a compass construction makes them.', '["which pair is perpendicular","angle between perpendicular lines","perpendicular in the environment","which tool checks a right angle"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_LINES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLES_STRAIGHT_LINE_IDENTIFY', 'MATH.G6.GEOMET.ANGLES', 'mathematics', 6, 'Identify angles on a straight line at a point', ARRAY['MATH.G6.GEOMET.ANGLES.a']::text[], 'The child picks out the angles that share a point on a straight line (they make a straight angle), and says that two or more angles on a straight line at a point lie along it, and names right, acute and obtuse ones.', '["which angles are on a line","name the angle type","how many angles on a line","angles in a cut round cake at a point"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_ANGLE_PROPERTIES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.ANGLES.MEASURE_ANGLES_PROTRACTOR', 'MATH.G6.GEOMET.ANGLES', 'mathematics', 6, 'Measure angles on a straight line at a point', ARRAY['MATH.G6.GEOMET.ANGLES.b']::text[], 'The child reads an angle on a protractor from the correct scale (starting from zero on the baseline) and finds the difference between two readings.', '["read the angle","which scale to use","difference between two readings","is the angle acute or obtuse?"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_ANGLE_MEASURE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.ANGLES.SUM_ANGLES_STRAIGHT_LINE', 'MATH.G6.GEOMET.ANGLES', 'mathematics', 6, 'Work out the sum of angles on a straight line', ARRAY['MATH.G6.GEOMET.ANGLES.c']::text[], 'The child knows that angles on a straight line at a point add up to 180 degrees and finds a missing angle (two or three angles, including an angle given as a multiple of another).', '["find the missing angle","three angles on a line","one angle is 4 times the other","spot the mistake"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_ANGLE_PROPERTIES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLE_SUM_RECT_TRIANGLE', 'MATH.G6.GEOMET.ANGLES', 'mathematics', 6, 'Determine the sum of angles in rectangles and triangles', ARRAY['MATH.G6.GEOMET.ANGLES.d']::text[], 'The child knows that the angles of a triangle add up to 180 degrees and the angles of a rectangle to 360 degrees (each 90 degrees), and finds a missing angle of a triangle.', '["missing angle of a triangle","sum of the angles of a rectangle","right-angled triangle other two angles","spot the mistake"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_TRIANGLE_PROPERTIES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.ANGLES.CONSTRUCT_TRIANGLES', 'MATH.G6.GEOMET.ANGLES', 'mathematics', 6, 'Construct equilateral, right-angled and isosceles triangles: their properties', ARRAY['MATH.G6.GEOMET.ANGLES.e']::text[], 'The child names a triangle from its sides and angles (three equal sides, a right angle, two equal sides), knows the angles of an equilateral triangle are all 60 degrees, and which sides are equal in an isosceles triangle. The construction itself is a practical.', '["name the triangle from its sides","which sides are equal","angle in an equilateral triangle","which triangle has a right angle"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_TRIANGLE_PROPERTIES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.ANGLES.INTERIOR_ANGLES_TRIANGLES', 'MATH.G6.GEOMET.ANGLES', 'mathematics', 6, 'Interior angles of equilateral, right-angled and isosceles triangles', ARRAY['MATH.G6.GEOMET.ANGLES.f']::text[], 'The child finds an unknown interior angle of an equilateral, right-angled or isosceles triangle using that the angles add to 180 degrees, the angles opposite equal sides are equal, and the right angle is 90 degrees. Measuring with a protractor is a practical.', '["missing angle of an isosceles triangle","angles of an equilateral triangle","other angle of a right-angled triangle","spot the mistake"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_TRIANGLE_PROPERTIES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CUBOID_CUBE_PARTS', 'MATH.G6.GEOMET.3_D_OBJECTS', 'mathematics', 6, 'Vertices, faces and edges of cuboids and cubes', ARRAY['MATH.G6.GEOMET.3_D_OBJECTS.a']::text[], 'The child counts the vertices (8), faces (6) and edges (12) of a cube or a cuboid, tells which faces are equal, works out the length of wire for the edges of a cube or cuboid, and matches a net to its solid.', '["how many faces, edges, vertices","wire for the frame","which net makes a cube","equal faces of a cuboid"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G6_3D_OBJECTS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CYLINDER_PARTS', 'MATH.G6.GEOMET.3_D_OBJECTS', 'mathematics', 6, 'Faces and edges of cylinders', ARRAY['MATH.G6.GEOMET.3_D_OBJECTS.b']::text[], 'The child says a cylinder has 2 flat circular faces, 1 curved surface and 2 curved edges, no vertices, and identifies cylinders in the environment (tin, pipe, drum).', '["faces of a cylinder","edges of a cylinder","does it have vertices","which object is a cylinder"]'::jsonb, '["recall"]'::jsonb, ARRAY['G6_3D_OBJECTS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.PLANE_FIGURES_IN_SOLIDS', 'MATH.G6.GEOMET.3_D_OBJECTS', 'mathematics', 6, 'Describe plane figures in 3-D objects', ARRAY['MATH.G6.GEOMET.3_D_OBJECTS.c']::text[], 'The child names the plane figure that is the shape of a face of a solid (squares on a cube, rectangles on a cuboid, circles on a cylinder, triangles on a pyramid) and a solid that has a given face.', '["which shape is the face","which solid has circular faces","what shapes make a pyramid","trace a face and name it"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_3D_OBJECTS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.FREQUENCY_TABLE', 'MATH.G6.DATA_H.BAR_GRAPHS', 'mathematics', 6, 'Draw and read a frequency table of data', ARRAY['MATH.G6.DATA_H.BAR_GRAPHS.a']::text[], 'The child tallies raw data into a frequency table, adds the frequencies to find the total, finds a missing frequency, and says which value is the most frequent.', '["total number asked","missing frequency","which is most frequent","complete a table from tallies"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_DATA_COLLECTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PICTOGRAPH', 'MATH.G6.DATA_H.BAR_GRAPHS', 'mathematics', 6, 'Represent data using pictographs', ARRAY['MATH.G6.DATA_H.BAR_GRAPHS.b']::text[], 'The child works out how many symbols a frequency needs when a symbol stands for more than one (2, 5 or 10), reads the key, and deals with half symbols.', '["symbols needed","what does the key say","value of a half symbol","complete a pictograph"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_DATA_COLLECTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PILING', 'MATH.G6.DATA_H.BAR_GRAPHS', 'mathematics', 6, 'Represent data through piling', ARRAY['MATH.G6.DATA_H.BAR_GRAPHS.c']::text[], 'The child says that in piling each object stands for one item counted, that the tallest pile is the most frequent, finds the total of all piles, and which pile has the fewest. The sorting and piling itself is a practical.', '["which pile is the biggest","total of the piles","difference between two piles","what does each counter stand for"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G6_DATA_COLLECTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_DRAW', 'MATH.G6.DATA_H.BAR_GRAPHS', 'mathematics', 6, 'Represent data using bar graphs', ARRAY['MATH.G6.DATA_H.BAR_GRAPHS.d']::text[], 'The child chooses a scale for the vertical axis, works out how many squares or what height a frequency needs, and says what a bar graph needs (a title, labelled axes, equal bar widths).', '["height of a bar","choose a scale","what is missing on the graph","squares for a frequency"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_DATA_COLLECTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_INTERPRET', 'MATH.G6.DATA_H.BAR_GRAPHS', 'mathematics', 6, 'Interpret information from bar graphs', ARRAY['MATH.G6.DATA_H.BAR_GRAPHS.e']::text[], 'The child reads values from a bar graph (including a scale that goes up in 2s, 5s or 10s), finds the difference between two bars, the total, and the second highest bar, and draws a conclusion.', '["read a bar","difference between two bars","second highest","what conclusion can we draw"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_DATA_COLLECTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
