INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.WRITE_AM_PM.M_QUARTER_TO_WRONG_HOUR', 'MATH.G6.MEASUR.TIME.WRITE_AM_PM', 'Writes quarter to six as 6:45 (quarter to is 15 minutes before the hour).', '{"question":"Quarter to 6 in the evening","wrong_answer":"6:45 p.m.","correct_answer":"5:45 p.m."}'::jsonb, 'Reads "quarter" as 45 minutes past.', 'Time with the hour not reduced.', 'On a clock, quarter to means the minute hand on 9: the hour hand has not reached the next hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.WRITE_AM_PM.M_EVENING_WITH_AM', 'MATH.G6.MEASUR.TIME.WRITE_AM_PM', 'Writes an evening or afternoon time with a.m.', '{"question":"Supper at half past 7 in the evening","wrong_answer":"7:30 a.m.","correct_answer":"7:30 p.m."}'::jsonb, 'Writes the time without thinking which half of the day.', 'The a.m. version of the time.', 'Ask whether it is before or after noon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PREPARE_BUDGET.M_ADD_INCOME_TO_SPENDING', 'MATH.G6.MEASUR.MONEY.PREPARE_BUDGET', 'Adds income and spending to find the balance.', '{"question":"Income 5,000, spending 3,200: balance?","wrong_answer":"8,200","correct_answer":"1,800"}'::jsonb, 'Adds all the numbers in the table.', 'Total of all amounts.', 'Balance is what is left after spending.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
