INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES.M_SELLING_LESS_BUYING_REVERSED', 'MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES', 'Subtracts selling price from buying price and gives a negative or reversed answer.', '{"question":"Bought at 500, sold at 650: profit?","wrong_answer":"-150 or 1,150","correct_answer":"150"}'::jsonb, 'Subtracts in the order written.', 'Reversed subtraction.', 'The bigger price comes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES.M_LOSS_AS_PROFIT', 'MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES', 'Calls the difference a profit even when the selling price is lower.', '{"question":"Bought at 900, sold at 700: profit or loss?","wrong_answer":"profit of 200","correct_answer":"loss of 200"}'::jsonb, 'Only knows the word profit.', 'Wording that suggests profit.', 'Compare the two prices; if selling is less there is a loss.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
